DELIMITER $$
CREATE PROCEDURE p_course_counts(IN p_cno CHAR(3), OUT p_chosen INT, OUT p_graded INT)
BEGIN
 SELECT COUNT(*),COUNT(Grade) INTO p_chosen,p_graded FROM sc WHERE Cno=p_cno;
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE p_grade_label(IN p_grade INT, OUT p_label VARCHAR(10))
BEGIN
 IF p_grade IS NULL THEN SET p_label='缺考'; ELSEIF p_grade>=60 THEN SET p_label='及格'; ELSE SET p_label='不及格'; END IF;
END$$
DELIMITER ;
